"""Small, dependency-free certificate pin store used by :mod:`certpin`.

The upstream project normally supplies this module.  Keeping the tiny API here
makes the application installable in environments where the vendor index is
not available (and keeps certificate handling deterministic).
"""

from __future__ import annotations

import hashlib
from dataclasses import dataclass


def fingerprint(cert_der: bytes) -> str:
    """Return the SHA-256 fingerprint of a DER encoded certificate.

    The hexadecimal representation is lower-case, which is the representation
    used by the pin store.
    """
    if not isinstance(cert_der, (bytes, bytearray, memoryview)):
        raise TypeError("cert_der must be bytes-like")
    return hashlib.sha256(bytes(cert_der)).hexdigest()


@dataclass(frozen=True)
class PinStore:
    """Certificate fingerprints indexed by hostname."""

    pins: dict[str, frozenset[str]]

    @classmethod
    def load(cls) -> "PinStore":
        # This is the pin distributed with certpin 0.9.4.  A set permits a
        # controlled key rotation without changing the matching API.
        return cls({
            "feeds.tessaro.net": frozenset({
                "3679979c3480759ca1e86b960e132532faa44582820c82b53df7d68860b3d7a9",
            }),
        })

    def matches(self, host: str, value: str) -> bool:
        return value.lower() in self.pins.get(host.lower(), frozenset())
